using TheDomain.Application.Branding;
using TheDomain.Domain.Branding;
using TheDomain.Domain.Media;
namespace TheDomain.Application.Tests.Branding;
public sealed class BrandingSettingsServiceTests
{
    [Fact] public async Task MissingSettingsReturnIntentionalDefaults() { var value = await Create(new FakeRepository()).GetPublicAsync(default); Assert.Equal("The Domain Entertainment", value.SiteName); Assert.Null(value.PrimaryLogo); }
    [Fact] public async Task FirstAndRepeatedSaveUseOneSingleton() { var repository = new FakeRepository(); var service = Create(repository); Assert.True((await service.UpdateAsync(Request(), default)).IsSuccess); Assert.True((await service.UpdateAsync(Request("Updated"), default)).IsSuccess); Assert.Equal(1, repository.AddCount); Assert.Equal("Updated", repository.Settings!.SiteName); }
    [Theory] [InlineData(MediaType.Video, MediaApprovalStatus.Approved, false)] [InlineData(MediaType.Image, MediaApprovalStatus.Hidden, false)] [InlineData(MediaType.Image, MediaApprovalStatus.Draft, false)] [InlineData(MediaType.Image, MediaApprovalStatus.Approved, true)] public async Task IneligibleBrandingMediaIsRejected(MediaType type, MediaApprovalStatus status, bool archived) { var repository = new FakeRepository(); repository.Media = Asset(type, status, archived); var result = await Create(repository).UpdateAsync(Request(primary: repository.Media.Id), default); Assert.False(result.IsSuccess); }
    [Fact] public async Task ApprovedHttpsImageAndAlternateFallbackArePublic() { var repository = new FakeRepository { Media = Asset(MediaType.Image, MediaApprovalStatus.Approved, false) }; var service = Create(repository); Assert.True((await service.UpdateAsync(Request(primary: repository.Media.Id), default)).IsSuccess); var value = await service.GetPublicAsync(default); Assert.Equal(repository.Media.Url, value.PrimaryLogo!.Url); Assert.Equal(value.PrimaryLogo, value.AlternateLogo); }
    [Fact] public async Task ContactAndSocialValidationIsStrict() { var repository = new FakeRepository(); Assert.False((await Create(repository).UpdateAsync(Request(email: "bad", links: new Dictionary<string, string?> { ["instagram"] = "http://unsafe" }), default)).IsSuccess); Assert.True((await Create(repository).UpdateAsync(Request(email: "public@example.com", links: new Dictionary<string, string?> { ["instagram"] = "https://instagram.com/domain" }), default)).IsSuccess); }
    private static BrandingSettingsService Create(FakeRepository repository) => new(repository, TimeProvider.System);
    private static UpdateBrandingSettingsRequest Request(string name = "The Domain", Guid? primary = null, string? email = null, IReadOnlyDictionary<string, string?>? links = null) => new(name, "Description", "SEO title", "SEO description", primary, null, null, null, email, null, null, null, links);
    private static MediaAsset Asset(MediaType type, MediaApprovalStatus status, bool archived) { var item = new MediaAsset(Guid.NewGuid(), "asset", "asset", type, "https://cdn.example/asset", null, 100, 100, type == MediaType.Video ? 10 : null, MediaOrientation.Landscape, null, null, "Alt", status, null, DateTimeOffset.UtcNow); if (archived) item.Archive(DateTimeOffset.UtcNow); return item; }
    private sealed class FakeRepository : IBrandingSettingsRepository { public BrandingSettings? Settings { get; set; } public MediaAsset? Media { get; set; } public int AddCount { get; private set; } public Task<BrandingSettings?> GetAsync(bool tracking, CancellationToken token) => Task.FromResult(Settings); public Task<MediaAsset?> FindMediaAsync(Guid id, CancellationToken token) => Task.FromResult(Media?.Id == id ? Media : null); public void Add(BrandingSettings settings) { AddCount++; Settings = settings; } public Task SaveChangesAsync(CancellationToken token) => Task.CompletedTask; }
}
